package com.coffeeshop.service;import com.coffeeshop.model.ReportModels;import com.coffeeshop.repository.ReportRepository;import java.time.LocalDate;import java.util.Objects;public final class ReportService{private final ReportRepository repository;public ReportService(ReportRepository r){repository=Objects.requireNonNull(r);}public ReportModels.Report report(LocalDate from,LocalDate to){if(from==null||to==null)throw new IllegalArgumentException("Select a start and end date.");if(to.isBefore(from))throw new IllegalArgumentException("End date cannot precede start date.");if(from.plusYears(2).isBefore(to))throw new IllegalArgumentException("Report range cannot exceed two years.");return repository.load(from,to);}}
